__NUXT_JSONP__("/kr/price", (function(a,b,c,d,e,f,g,h,i,j,k,l){return {data:[{details:{slug:b,pageTitle:"가격 | Mentor Language Institute",pageDescription:"만약 저희 학교에서 제공하는 숙박 시설이 필요 없을 경우에는 ②숙박비를 지불하실 필요가 없습니다.",title:"가격",image:"\u002Fimages\u002Fprices\u002Fprice\u002Fget-a-quote.jpg",button:{lists:[{link:["\u003Ca class=\"btn btn-primary\" href=\"\u002Fkr\u002Fprice-auto\"\u003E가격 계산기\u003C\u002Fa\u003E"]}]},steps:{title:"①학비＋②숙박비＋③기타 비용",subtitle:["만약 저희 학교에서 제공하는 숙박 시설이 필요 없을 경우에는 ②숙박비를 지불하실 필요가 없습니다.\u003Cbr\u003E* \u003Ca href=\"\u002Fkr\u002Fprice-auto\u002F\"\u003E가격 계산기\u003C\u002Fa\u003E 를 사용하세요."],lists:[{title:"①학비",subtitle:["가격은 프로그램과 등록 기간에 따라 변경 됩니다.\u003Cbr \u002F\u003E 더 많은 기간을 등록할수록, 더 많은 할인을 받으실 수 있습니다."],image:"\u002Fimages\u002Fprices\u002Fprice\u002FPRICE_CHART_WEB_JAN06.jpg",description:["\u003Cb\u003E질문과 답변\u003C\u002Fb\u003E","\u003Cb\u003E질문1: 신용카드로 결제할 수 있나요? \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003E답변1:\u003C\u002Fb\u003E 네, 신용카드로 결제하실 수 있습니다. 하지만 4%의 서비스 수수료가 추가됩니다.","\u003Cb\u003EQ2: MLI에 어떤 결제 방법으로 지불할 수 있나요? \u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003EA2:\u003C\u002Fb\u003E 다음 결제 방법을 이용하실 수 있습니다: \u003Cbr\u003E • 은행 송금 \u003Cbr\u003E • 국제 송금 \u003Cbr\u003E • 현금 \u003Cbr\u003E • 개인 수표 \u003Cbr\u003E • 신용카드 \u003Cbr\u003E • 데빗카드 \u003Cbr\u003E • Zelle","신용카드\u002F직불카드 결제 시 발생하는 4% 서비스 수수료를 피하고 싶으시다면, 다음 대체 결제 방법 중 하나를 선택하실 수 있습니다:\u003Cbr\u003E\u003Cb\u003E은행 송금, 국제 송금(은행 수수료 $35 발생), 현금, 개인 수표 또는 Zelle.\u003C\u002Fb\u003E","\u003Cb\u003E질문3: 프로그램이 시작된 후 학비를 낼 수 있나요? \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003E답변3:\u003C\u002Fb\u003E 아니요. 학비는 프로그램 시작일 전 또는 첫날까지 전액 납부해야 합니다."]},{title:"②숙박비",subtitle:["우리는 학생들에게 홈스테이, 기숙사를 제공합니다.미국 문화를 경험하고 싶은 학생에게는 홈스테이를 추천하고 많은 친구들을 만나고 싶은 학생들에게는 기숙사를 추천합니다."],category:[{title:"홈스테이 가격",table:{tableMaxCol:3,title:"배치 수수료* : $300\u003Cbr \u002F\u003E 18세 미만인 경우 임대료는 18세 이상인 사람의 가격보다 약 10% 더 높습니다.",thead:[c,d,"Shared(2인실)***"],tbody:[[e,a,a],[f,"$436","$384"],[g,"$872","$768"],[h,"$1,308","$1,152"],[i,"$1,744","$1,536"],[j,"$3,160","$2,904"],[k,"$4,740","$4,356"]]}},{title:"기숙사 가격",table:{tableMaxCol:4,title:"배치수수료* : $200\u003Cbr \u002F\u003E 18세 미만인 경우 임대료는 18세 이상인 사람의 가격보다 약 10% 더 높습니다.",thead:[c,d,"Shared(2인실)","Quad(4인실)"],tbody:[[e,a,a,a],[f,"$570","$430","$315"],[g,"$1,140","$860","$630"],[h,"$1,710","$1,290","$945"],[i,"$2,280","$1,720","$1,260"],[j,"$4,320","$3,080","$2,320"],[k,"$6,480","$4,620","$3,480"]]},description:["*배치 수수료는 한 번만 지불 하시면 되나 환불은 안됩니다.\u003Cbr \u002F\u003E**보증금은 학생들이 퇴거후에 환불 됩니다.\u003Cbr \u002F\u003E***만약 Shared(2인실)을 신청했을 경우에는, \u003Cspan class=\"rmarker\"\u003E 반드시 다른 학생과 같이 방을 사용해야합니다. \u003C\u002Fspan\u003E","※숙박 서비스는 U.S. Support Service 또는 다른 에이전트로부터 제공됩니다.","\u003Ca href=\"\u002Fkr\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E  숙박에 대한 더 많은 정보\u003C\u002Fa\u003E"]}]},{title:"③ 초기 지불액",subtitle:["위에 명시된 요금 외에 등록시 지불해야 될 요금이 있습니다."],lists:[l,"I-20 배송비**: $120","SEVIS 요금**: $350(SEVP에 바로 지불 됩니다.)","교과서: $150 - $240"],description:["*환불 안됩니다.\u003Cbr \u002F\u003E** 학생 비자를 신청할 경우에만 적용됩니다."]}]},examples:{title:"예시",subtitle:["가격에 대한 예입니다: 4 주 그리고 48주"],lists:[{title:"1개월(4주)",items:[l,"학비: $1,220","숙박 요금: $1,630（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003E총 금액: $3,000\u003C\u002Fspan\u003E"]},{title:"1년(48주)",items:["초기 지불 금액: $150","학비: $10,032","숙박 요금: $13,810（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003E총 금액: $23,992\u003C\u002Fspan\u003E"]}]},other_info:["금액에 대해서 문의 사항이 있으시면, 언제든지 저희에게 연락주세요."],dir:"\u002Fprice",path:"\u002Fprice\u002Fkr",extension:".json",createdAt:"2026-10-22T16:31:30.175Z",updatedAt:"2026-03-24T13:34:16.713Z"},lang:b}],fetch:{},mutations:void 0}}("$300","kr","","Private(1인실)","\u003Cb\u003E보증금**\u003C\u002Fb\u003E","1 주","2 주","3 주","4 주","8 주","12 주","등록비: $150")));